#!/usr/bin/env bash
set -e

echo '=================================================='
echo '  Docpersian - به‌روزرسانی نهایی و رفع خطاهای ورودی و خروجی'
echo '=================================================='

# ۱. یافتن مسیر پروژه
if [ -d '/root/docushift' ]; then
  cd /root/docushift
elif [ -d '/root/Docpersian' ]; then
  cd /root/Docpersian
elif [ -f 'server.ts' ]; then
  echo 'در پوشه فعلی هستیم.'
else
  TARGET_DIR=$(pm2 jlist 2>/dev/null | grep -o '"pm_cwd":"[^"]*"' | head -n1 | cut -d'"' -f4)
  if [ -n "$TARGET_DIR" ] && [ -d "$TARGET_DIR" ]; then
    cd "$TARGET_DIR"
  else
    TARGET_DIR=$(find /var/www /home /root /opt -maxdepth 3 -name 'server.ts' -not -path '*/node_modules/*' 2>/dev/null | head -n1 | xargs dirname 2>/dev/null)
    if [ -n "$TARGET_DIR" ] && [ -d "$TARGET_DIR" ]; then
      cd "$TARGET_DIR"
    else
      echo 'خطا: پوشه پروژه پیدا نشد! لطفا دستی cd /root/docushift کنید.'
      exit 1
    fi
  fi
fi

echo "--> مسیر پروژه: /app/applet"

# ۲. استخراج کدهای اصلاح‌شده (فونت‌ها، حروف‌چینی فارسی، رفع رفرش ورودی)
echo '--> در حال اعمال کدهای اصلاح‌شده...'
cat << 'EOF_B64' | base64 -d | tar -xz --overwrite

EOF_B64

echo '  ✓ فایل‌های سورس با موفقیت به‌روزرسانی شدند.'

# ۳. پاکسازی کش ترجمه‌های قدیمی برای جلوگیری از استفاده از متن وارونه قبلی
echo '--> پاکسازی کش ترجمه‌های قدیمی...'
rm -rf jobs_storage/cache/* 2>/dev/null || true

# ۴. دانلود فونت‌های وزیرمتن در صورت نیاز
mkdir -p server/assets/fonts
if [ ! -s server/assets/fonts/persian-font.ttf ]; then
  echo '--> دانلود فونت وزیرمتن عادی...'
  curl -sL "https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@master/fonts/ttf/Vazirmatn-Regular.ttf" -o server/assets/fonts/persian-font.ttf 2>/dev/null || true
fi
if [ ! -s server/assets/fonts/persian-font-bold.ttf ]; then
  echo '--> دانلود فونت وزیرمتن بولد...'
  curl -sL "https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@master/fonts/ttf/Vazirmatn-Bold.ttf" -o server/assets/fonts/persian-font-bold.ttf 2>/dev/null || true
fi

# ۵. کامپایل فرانت‌اند
echo '--> کامپایل فرانت‌اند (npm run build)...'
npm run build

# ۶. ری‌استارت سرور
echo '--> راه‌اندازی مجدد سرویس با PM2...'
pm2 restart all --update-env 2>/dev/null || pm2 restart 0 --update-env 2>/dev/null

echo '=================================================='
echo '  ✓ به‌روزرسانی با موفقیت کامل شد!'
echo '  اکنون پنل را باز کرده و فایل خود را ترجمه فرمایید.'
echo '=================================================='
